# Benny A3-3 smile patch v2. Only changes Sprite2DRuntime.tsx.
$ErrorActionPreference = "Stop"
$target = Join-Path (Get-Location) "apps\desktop\frontend\src\runtimes\sprite2d\Sprite2DRuntime.tsx"
if (-not (Test-Path -LiteralPath $target -PathType Leaf)) { throw "Please run from OpenMimicry project root." }
$expected = "DCF1A59DFCB62CFB98E3D391B1D3E3D093BE5C3DFE5A0087A737C0BFEF18C58D"
$actual = (Get-FileHash -LiteralPath $target -Algorithm SHA256).Hash
if ($actual -ne $expected) { throw "Original file differs from uploaded copy; no changes made." }
$backup = "$target.before-happy-$(Get-Date -Format yyyyMMdd-HHmmss).bak"
Copy-Item -LiteralPath $target -Destination $backup -ErrorAction Stop
$compressed = [Convert]::FromBase64String("")
$inputStream = New-Object System.IO.MemoryStream(,$compressed)
$gzipStream = New-Object System.IO.Compression.GZipStream($inputStream,[System.IO.Compression.CompressionMode]::Decompress)
$outputStream = New-Object System.IO.MemoryStream
try {
  $gzipStream.CopyTo($outputStream)
  [System.IO.File]::WriteAllBytes($target,$outputStream.ToArray())
} finally {
  $gzipStream.Dispose(); $inputStream.Dispose(); $outputStream.Dispose()
}
Write-Host "PATCH OK" -ForegroundColor Green
Write-Host "BACKUP: $backup"
Write-Host "UPDATED: $target"
